from lib import *
S = SS('g2')
steps = [
    step("接口值的大小只和“是不是接口”有关:unsafe.Sizeof 得到 any = 16、io.Reader = 16、Summer(自定义的单方法接口)= 16 字节;对照 *T = 8、T(两个 int)= 16、string = 16、[]int = 24。零值 any(nil) 的两个字都是 nil。", t=tl(S(1)), done=lidx(S(1), 'any = 16'), mark=lidx(S(1), '零值 any(nil)'), b=bars([['any / io.Reader / Summer', 16, '16 字节'], ['*T', 8, '8 字节'], ['T(两个 int)', 16, '16 字节'], ['string', 16, '16 字节'], ['[]int', 24, '24 字节']], 24, done=[0], mark=[1]), kv=KV([['任意接口值', '2 个机器字 = 16 字节'], ['零值 any', 'typ == nil 且 data == nil'], ['*T / T', '8 / 16 字节'], ['string / []int', '16 / 24 字节']], ['任意接口值'])),
    step("把 any 按 {typ, data} 读出来:any(42) 与 any(1000) 类型字相同,与 any(\"hi\") 不同;*(*int)(data) 分别读到 42 与 1000;两个 any(1000) 的 data 指针不同(两个值各有自己的一份数据);any(\"hi\") 的 data 指向字符串头,len = 2、内容 \"hi\"。指针类型不同:any(&T) 的 data 指针与原指针 p 相同。把 T 值装进 any 之后再把 v.A 改成 100:v.A = 100,接口里的拷贝仍是 {A:1 B:2},data 指针不是 &v。", t=tl(S(2)), done=lidx(S(2), 'any(42) 与 any(1000)', 'any(\"hi\"):data'), mark=lidx(S(2), 'any(&T)', 'var av any = v'), kv=KV([['any(42) / any(1000)', '同一个类型字,data 指向各自的值'], ['any(\"hi\")', 'data 指向字符串头,len = 2'], ['any(&T)', 'data == 原指针'], ['T 值装进 any', 'data 指向拷贝:v.A = 100 后拷贝仍是 {1 2}']], ['any(&T)'])),
    step("带方法的接口 iface 第一个字是 itab 指针。两个 Summer 都装 *T:itab 指针相同,itab.typ 等于 any(&T) 的类型字;itab.fun[0] 指向 main.(*T).Sum,与 reflect 取到的 (*T).Sum 地址相同。同一个动态类型 *bytes.Buffer 装进 io.Reader 与 io.ReadWriter:itab 指针不同、itab.inter 不同、itab.typ 相同。自定义接口 RWC(声明顺序 Write、Read、Close)装 F{}:itab.fun[0..2] 依次是 main.(*F).Close、main.(*F).Read、main.(*F).Write,即按方法名排序。", t=tl(S(3)), done=lidx(S(3), '两个 Summer 都装着', 'itab.fun[0] 指向'), mark=lidx(S(3), 'io.Reader 与 io.ReadWriter', 'RWC 的 itab.fun[0]', 'RWC 的 itab.fun[1]', 'RWC 的 itab.fun[2]'), kv=KV([['itab 的内容', 'inter(接口类型)、typ(动态类型)、hash、fun[](方法地址)'], ['两个 *T 装进 Summer', '共用一个 itab'], ['*bytes.Buffer 装进两种接口', '两个 itab,typ 相同、inter 不同'], ['方法顺序', '按方法名排序:Close、Read、Write']], ['*bytes.Buffer 装进两种接口'])),
    step("itab 的来历:编译器看得出类型的转换(static 函数把 *T 返回为 Summer),汇编里直接引用 go:itab.*main.T,main.Summer(SB) 这个链接时生成的符号;运行时才知道类型的断言(dynamic 函数的 x.(Summer))调用 runtime.typeAssert。这个断言稳态下每次调用 0 次分配。", t=tl(S(4)), done=lidx(S(4), 'main.static 的汇编', 'go:itab.*main.T,main.Summer'), mark=lidx(S(4), 'runtime.typeAssert', '稳态每次调用的分配次数:0'), kv=KV([['static:*T → Summer', 'MOVD $go:itab.*main.T,main.Summer(SB)'], ['dynamic:x.(Summer)', 'CALL runtime.typeAssert'], ['断言稳态分配', '0 次/调用']], ['dynamic:x.(Summer)'])),
    step("接口调用的成本(callee 都是 //go:noinline,testing.Benchmark,7 轮取中位数):直接调用 1.98 ns/op、经接口 1.97 ns/op;4096 个接口里全是同一种类型逐个调用 1.99 ns/op,换成 4 种类型按伪随机排列逐个调用 7.23 ns/op(最小 7.21、最大 7.25)。同一份方法表,变慢的是类型不固定时间接跳转的目标不好预测——这是对现象的解释,我没有用硬件计数器验证。", t=tl(S(5)), done=lidx(S(5), '直接调用', '经接口', '同类型'), mark=lidx(S(5), '4 类型随机'), b=bars([['直接调用 ns/op', 1.98, '1.98'], ['经接口 ns/op', 1.97, '1.97'], ['4096 个同类型 ns/op', 1.99, '1.99'], ['4096 个 4 类型随机 ns/op', 7.23, '7.23']], 7.23, done=[0, 1, 2], mark=[3]), kv=KV([['直接调用', '1.98 ns/op'], ['经接口(单一类型)', '1.97 ns/op'], ['4096 个同类型', '1.99 ns/op'], ['4096 个 4 类型随机', '7.23 ns/op']], ['4096 个 4 类型随机'])),
]
A = mkartg('g2', 2, 'Go,接口,iface,eface,itab,unsafe,真实验证,动画演示',
    '用 unsafe 把 Go 1.27.1 的接口值按 {typ, data} 与 {itab, data} 读出来:接口值 16 字节,指针类型直接放进 data 字、值类型是一份拷贝,itab 里是接口类型、动态类型与按方法名排序的方法地址,同一个动态类型装进两种接口得到两个 itab;编译期已知的转换引用 go:itab 符号、断言走 runtime.typeAssert;接口调用在类型固定时与直接调用一样快(约 2 ns),4 种类型随机时约 7.2 ns。',
    '接口值看起来是一个对象,实际上只是两个字。这篇不靠源码推测,直接用 unsafe 把接口值拆开读:看类型字和数据字各装了什么、itab 里有什么、同一个类型装进不同接口时 itab 是不是同一个,再用汇编和基准测试量出调用的真实成本。',
    [('16 字节', '任意接口值(any、io.Reader、自定义接口)的大小,两个机器字'), ('同一 itab', '两个 *T 装进 Summer 共用一个 itab;同一个 *bytes.Buffer 装进 io.Reader 和 io.ReadWriter 是两个 itab'), ('2 ns → 7 ns', '通过接口调用:4096 个同类型 1.99 ns/op,4 种类型伪随机 7.23 ns/op')],
    [('接口值有多大', '<p>空接口和带方法的接口都是两个字,只是第一个字不同:<code>any</code>(<code>eface</code>)放类型指针,带方法的接口(<code>iface</code>)放 <code>itab</code> 指针。运行时源码里两者的定义在 <code>internal/abi/iface.go</code>:<code>EmptyInterface{Type, Data}</code> 与 <code>ITab{Inter, Type, Hash, Fun}</code>,下面的实验用同样的布局把接口值读出来。</p>'),
     ('any 的两个字:类型 + 数据', '<p>数据字有两种用法:<b>指针类型</b>(<code>*T</code>)直接把指针放进数据字,不再多一层;<b>非指针类型</b>(<code>T</code>、<code>int</code>、<code>string</code>)的数据字指向一份值的拷贝,所以装进接口之后再改原变量,接口里的值不变。字符串的数据字指向的是字符串头(指针 + 长度),不是字符内容本身。</p>'),
     ('带方法的接口:itab', '<p><code>itab</code> 是“(接口类型, 动态类型)”这一对的方法表:相同的一对共用同一个 itab,所以两个 <code>*T</code> 装进 <code>Summer</code> 得到同一个指针;同一个 <code>*bytes.Buffer</code> 装进 <code>io.Reader</code> 与 <code>io.ReadWriter</code> 是两对,得到两个 itab。方法地址按方法名排序,而不是按接口里声明的顺序。注意最后一行:<code>F</code> 的方法是值接收者,itab 里放的却是 <code>main.(*F).Close</code>——数据字永远是个指针,所以 itab 里放的是接收指针的包装函数(名字来自实测输出,包装的具体实现我没有去读)。</p>'),
     ('itab 是什么时候造出来的', '<p>编译器能确定的转换(<code>return t</code> 里把 <code>*T</code> 变成 <code>Summer</code>)只有一条汇编:取 <code>go:itab.*main.T,main.Summer</code> 这个符号的地址,没有任何运行时查找。运行时才知道类型的断言(<code>x.(Summer)</code>)要调用 <code>runtime.typeAssert</code>;稳态下它不分配内存。运行时源码 <code>runtime/iface.go</code> 里的 <code>getitab</code> 与 <code>itabTable</code> 就是这类 itab 的缓存,不过本文没有去量缓存命中与未命中的差别。</p>'),
     ('通过接口调用的成本', '<p>在这个最小的例子里,经接口调用与直接调用没有可测的差别(1.97 与 1.98 ns/op),两者都被 <code>//go:noinline</code> 的调用本身占满了。真正拉开差距的是类型不固定:4096 个接口里随机放 4 种类型,每次间接跳转的目标都在变,耗时变成 7.23 ns/op。把它当成“接口调用本身便宜,类型多变会让它变贵”的一个数据点,不要套用到别的程序上。</p>')],
    steps,
    [ENV_G + '。读过的运行时源码:internal/abi/iface.go(ITab 与 EmptyInterface 的布局)、runtime/iface.go(getitab 与 itabTable 的存在);用 unsafe 按同样布局读接口值,itab 地址只比较相等与否,不打印具体值;汇编用 go build -gcflags=-S 取得;基准测试每个变体 7 轮取中位数',
     '没有验证:32 位平台与其它架构上的接口调用成本、泛型(GC shape 字典)里的接口表示、reflect 构造的接口、type switch 的缓存实现与 itab 表扩容、PGO 去虚拟化(见后面的 PGO 一篇)、7.23 ns 变慢的原因是否确实是分支预测(没有用硬件计数器看)'],
    '接口的内存布局')
